btoa('hello')
// 'aGVsbG8='

btoa('héllo')
// 'aOlsbG8='  (é is U+00E9, which fits in one Latin-1 byte, E9)

btoa('😀')
// Typical browser console output (wording varies by browser):
// Uncaught DOMException: Failed to execute 'btoa' on 'Window': The string to be encoded contains characters outside of the Latin1 range.

function base64EncodeUnicode(str) {
  const bytes = new TextEncoder().encode(str);
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

base64EncodeUnicode('😀')
// '8J+YgA=='

base64EncodeUnicode('héllo')
// 'aMOpbGxv'

function base64DecodeUnicode(b64) {
  const binary = atob(b64);
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

base64DecodeUnicode('8J+YgA==')
// '😀'

base64DecodeUnicode('aMOpbGxv')
// 'héllo'

Buffer.from('😀', 'utf8').toString('base64')
// '8J+YgA=='

Buffer.from('8J+YgA==', 'base64').toString('utf8')
// '😀'
